import { mkdir, readFile, rm, writeFile } from "node:fs/promises";
import path from "node:path";

/**
 * Where uploaded files live. Local disk today; an S3-compatible
 * implementation can be added behind the same interface.
 */
export interface BlobStorage {
  put(key: string, data: Buffer): Promise<void>;
  get(key: string): Promise<Buffer | null>;
  delete(key: string): Promise<void>;
}

/** Keys are generated by the app: "<clubId>/<assetId>.<ext>". Nothing else is accepted. */
export const STORAGE_KEY = /^[0-9a-f-]{36}\/[0-9a-f-]{36}\.(png|jpg)$/;

export class LocalStorage implements BlobStorage {
  private readonly root: string;

  constructor(root: string) {
    this.root = path.resolve(root);
  }

  private resolve(key: string): string {
    if (!STORAGE_KEY.test(key)) throw new Error("Invalid storage key");
    const full = path.resolve(this.root, key);
    // Defence in depth: the regex already excludes "..", but never leave the root.
    if (!full.startsWith(this.root + path.sep)) throw new Error("Invalid storage key");
    return full;
  }

  async put(key: string, data: Buffer): Promise<void> {
    const file = this.resolve(key);
    await mkdir(path.dirname(file), { recursive: true });
    await writeFile(file, data, { flag: "wx" }); // never overwrite: assets are immutable
  }

  async get(key: string): Promise<Buffer | null> {
    try {
      return await readFile(this.resolve(key));
    } catch (error) {
      if ((error as NodeJS.ErrnoException).code === "ENOENT") return null;
      throw error;
    }
  }

  async delete(key: string): Promise<void> {
    await rm(this.resolve(key), { force: true });
  }
}
